<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientLogoUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientLogoUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withLogoUri,
 * getLogoUri/logoUri accessors, and isLogoUriChanged with/without original.
 */
class TrustedClientLogoUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withLogoUri creates a new instance with the LogoUri set
     * from a string value, and getLogoUri returns the primitive string.
     */
    public function testWithLogoUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientLogoUriAccessorUnitTest();

        // Act
        $result = $holder->withLogoUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getLogoUri());
    }
    /**
     * Asserts that withlogoUri has access to the value object
     * from a string value, and getLogoUri returns the primitive string.
     */
    public function testWithLogoUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientLogoUriAccessorUnitTest();

        // Act
        $result = $holder->withLogoUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->logoUri()->value());
    }
    public function testChangedLogoUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientLogoUriAccessorUnitTest();
        $original = $holder->withLogoUri('one');
        $same = $holder->withLogoUri('one');
        $modified = $holder->withLogoUri('other');

        // Act
        $unchanged = $holder->isLogoUriChanged();
        $withSame = $original->isLogoUriChanged($same);
        $withDiferent = $original->isLogoUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientLogoUriAccessorUnitTest
{
    use TrustedClientLogoUriAccessor;
}
